script:
country_event = { # Release the Forgotten
	id = paragon.5050
	title = "paragon.5050.name"
	desc = "paragon.5050.desc"
	picture = GFX_evt_board_meeting
	show_sound = event_conversation

	is_triggered_only = yes

	trigger = {
		exists = ruler
		ruler = { has_leader_flag = paragon_origin_legendary_leader }
	}

	immediate = {
		every_owned_pop_group = {
			limit = {
				has_any_ethic = yes
				NOT = { has_ethic = ethic_egalitarian }
			}
			pop_group_transfer_ethic = {
				POP_GROUP = this
				ETHOS = ethic_egalitarian
				PERCENTAGE = 0.1
			}
		}
	}

	option = {
		name = paragon.5050.a
		start_situation = {
			type = paragon_origin_forgotten
		}
		add_modifier = {
			modifier = paragon_origin_reformists_empire
			days = -1
		}
	}
}

