					limit = {
						is_colony = yes
						has_owner = yes
						is_owned_by	= root
						is_controlled_by = root
						NOT = { has_modifier = paragon_origin_reformists }
						any_owned_pop_group = { has_ethic = ethic_egalitarian }
					}
					add_modifier = {
						modifier = paragon_origin_reformists
