			}
		}
		export_trigger_value_to_variable = {
			trigger = count_owned_planet
			variable = max_reformists_planets
		}
		change_variable = {
			which = max_reformists_planets
			value = -1
		}
		divide_variable = {
			which = max_reformists_planets
			value = 2.1
		}
		ceiling_variable = max_reformists_planets
		if = {
			limit = {
				any_system_within_border = {
					is_capital_system = no
					any_system_planet = {
						is_colony = yes
						has_owner = yes
						is_owned_by	= root
						is_controlled_by = root
					}
				}
			}
			random_system_within_border = {
				limit = {
					is_capital_system = no
					any_system_planet = {
						is_colony = yes
						has_owner = yes
						is_owned_by	= root
						is_controlled_by = root
					}
				}
				random_system_planet = {
					limit = {
						is_colony = yes
					}
					save_event_target_as = first_reformist_planet
				}
			}
		}
		else = {
			capital_scope = { save_event_target_as = first_reformist_planet }
		}
	}

	option = {
		name = paragon.5062.a
		custom_tooltip = paragon.5062.a.tt
		event_target:first_reformist_planet = {
			hidden_effect = {
				while = {
					count = 2
					pop_group_transfer_ethic = {
						ETHOS = ethic_egalitarian
						AMOUNT = 100
					}
				}
			}
			add_modifier = {
				modifier = paragon_origin_reformists
				clear_on_owner_change = yes
				days = -1
			}
		}
		while = {
			count = max_reformists_planets
			random_system_within_border = {
				limit = {
					is_capital_system = no
					any_system_planet = {
						is_colony = yes
						has_owner = yes
						is_owned_by	= root
						is_controlled_by = root
						NOT = { has_modifier = paragon_origin_reformists }
